declare namespace d = "java:net.sf.saxon.value.DateTimeValue";
declare namespace saxon = "http://saxon.sf.net/";
let $dt1 := xs:dateTime('2012-05-01T12:00:00')
let $dt2 := xs:dateTime('2012-05-02T12:00:00')
let $j1 as xs:decimal := d:toJulianInstant($dt1)
let $j2 as xs:decimal := d:toJulianInstant($dt2)
return $j2 - $j1

